/// Pure Dart post-processing of offline Android image labels.
///
/// Extracted/adapted from the pinned Cantiere vision service. Image decoding,
/// ML Kit model inference, file limits and RAM checks remain the Android
/// host bridge's responsibility. No IO, telemetry, network or Cloud routing.
class LocalImageLabel {
  const LocalImageLabel(this.name, this.confidence);
  final String name;
  final double confidence;
}

class LocalImageLabelResult {
  const LocalImageLabelResult({required this.labels, required this.text});
  static const String providerId = 'localImageLabels';
  final List<LocalImageLabel> labels;
  final String text;
  bool get hasCategories => labels.isNotEmpty;
}

abstract final class LocalImageLabelProcessor {
  static const double minConfidence = 0.55;
  static const int maxLabels = 5;

  static LocalImageLabelResult fromNative(Iterable<Object?> rawLabels) {
    final labels = <LocalImageLabel>[];
    for (final item in rawLabels) {
      if (item is! Map) continue;
      final rawName = item['label'];
      final rawConfidence = item['confidence'];
      if (rawName is! String || rawConfidence is! num) continue;
      final name = rawName.trim().replaceAll(RegExp(r'\s+'), ' ');
      final confidence = rawConfidence.toDouble();
      if (name.isEmpty ||
          name.length > 70 ||
          !confidence.isFinite ||
          confidence < minConfidence ||
          confidence > 1) {
        continue;
      }
      labels.add(LocalImageLabel(name, confidence));
    }
    labels.sort((a, b) => b.confidence.compareTo(a.confidence));
    final selected = List<LocalImageLabel>.unmodifiable(labels.take(maxLabels));

    if (selected.isEmpty) {
      return const LocalImageLabelResult(
        labels: <LocalImageLabel>[],
        text: 'Non ho riconosciuto categorie visive con sufficiente '
            'affidabilità in questa foto. Il riconoscitore offline attuale '
            'è limitato; non posso descrivere dettagli, colori o testo '
            'dell\'immagine. Nessun dato è stato inviato al Cloud.',
      );
    }
    final detected = selected.map(
      (label) => '${label.name} (${(label.confidence * 100).round()}%)',
    );
    return LocalImageLabelResult(
      labels: selected,
      text: 'Riconoscimento visivo sul dispositivo (categorie probabili): '
          '${detected.join(', ')}.\n'
          'Queste sono etichette stimate da un classificatore offline, '
          'non una descrizione completa. Non posso ancora dedurre con '
          'affidabilità colori, quantità, testo o altri dettagli della foto. '
          'Nessuna immagine è stata inviata al Cloud.',
    );
  }
}

package com.aiorchestrator

import android.content.Context
import android.app.ActivityManager
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Handler
import android.os.Looper
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.label.ImageLabeling
import com.google.mlkit.vision.label.defaults.ImageLabelerOptions
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.File
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Offline image-category recognition. The bundled ML Kit model does not
 * contact an API, understand fine details, or run a multimodal LLM.
 * Never log image paths, labels, bytes, or user questions.
 */
internal object LocalImageVisionBridge {
    private const val channel = "com.aiorchestrator/local_image_vision"
    private const val maxBytes = 8L * 1024 * 1024
    private const val maxDecodedEdge = 1024
    private val busy = AtomicBoolean(false)
    private val worker = Executors.newSingleThreadExecutor()
    private val main = Handler(Looper.getMainLooper())

    fun register(context: Context, engine: FlutterEngine) {
        val appContext = context.applicationContext
        MethodChannel(engine.dartExecutor.binaryMessenger, channel)
            .setMethodCallHandler { call, result ->
                if (call.method != "labelImage") {
                    result.notImplemented()
                    return@setMethodCallHandler
                }
                val path = call.argument<String>("path")
                if (path.isNullOrBlank()) {
                    result.error("INVALID_IMAGE", "Nessuna immagine selezionata.", null)
                    return@setMethodCallHandler
                }
                if (!busy.compareAndSet(false, true)) {
                    result.error("IMAGE_BUSY", "Analisi locale già in corso.", null)
                    return@setMethodCallHandler
                }
                worker.execute {
                    try {
                        val file = File(path)
                        if (!file.isFile || !file.canRead() ||
                            file.length() !in 1L..maxBytes) {
                            main.post {
                                busy.set(false)
                                result.error("INVALID_IMAGE", "Immagine non disponibile o oltre 8 MB.", null)
                            }
                            return@execute
                        }

                        // Refuse a new vision workload if Android is already
                        // under memory pressure. Keep the resident text model
                        // untouched; a single image is never worth an OOM crash.
                        val activityManager = appContext.getSystemService(
                            Context.ACTIVITY_SERVICE
                        ) as? ActivityManager
                        val memory = ActivityManager.MemoryInfo()
                        activityManager?.getMemoryInfo(memory)
                        if (activityManager != null &&
                            (memory.lowMemory || memory.availMem < 256L * 1024 * 1024)) {
                            main.post {
                                busy.set(false)
                                result.error(
                                    "LOCAL_VISION_MEMORY",
                                    "Memoria libera insufficiente per Image LOCAL. " +
                                        "Chiudi altre applicazioni e riprova.",
                                    null
                                )
                            }
                            return@execute
                        }

                        // Decode bounds first, then a downsampled RGB_565 bitmap
                        // to bound peak RAM on devices with small memory budgets.
                        val bounds = BitmapFactory.Options().apply {
                            inJustDecodeBounds = true
                        }
                        BitmapFactory.decodeFile(file.path, bounds)
                        val width = bounds.outWidth
                        val height = bounds.outHeight
                        if (width <= 0 || height <= 0 || width > 16384 || height > 16384) {
                            main.post {
                                busy.set(false)
                                result.error("INVALID_IMAGE", "Formato o dimensioni immagine non supportati.", null)
                            }
                            return@execute
                        }
                        var sampleSize = 1
                        while (width / sampleSize > maxDecodedEdge ||
                            height / sampleSize > maxDecodedEdge) {
                            sampleSize *= 2
                        }
                        val options = BitmapFactory.Options().apply {
                            inSampleSize = sampleSize
                            inPreferredConfig = Bitmap.Config.RGB_565
                        }
                        val bitmap = BitmapFactory.decodeFile(file.path, options)
                            ?: throw IllegalArgumentException("cannot decode image")
                        main.post {
                            val labeler = ImageLabeling.getClient(
                                ImageLabelerOptions.Builder()
                                    .setConfidenceThreshold(0.55f)
                                    .build()
                            )
                            try {
                                labeler.process(InputImage.fromBitmap(bitmap, 0))
                                    .addOnSuccessListener { labels ->
                                        val payload = labels
                                            .sortedByDescending { it.confidence }
                                            .take(5)
                                            .map {
                                                mapOf(
                                                    "label" to it.text,
                                                    "confidence" to it.confidence.toDouble()
                                                )
                                            }
                                        result.success(payload)
                                    }
                                    .addOnFailureListener {
                                        result.error(
                                            "LOCAL_VISION_FAILED",
                                            "Riconoscimento visivo locale non riuscito.",
                                            null
                                        )
                                    }
                                    .addOnCompleteListener {
                                        bitmap.recycle()
                                        labeler.close()
                                        busy.set(false)
                                    }
                            } catch (_: Exception) {
                                bitmap.recycle()
                                labeler.close()
                                busy.set(false)
                                result.error(
                                    "LOCAL_VISION_FAILED",
                                    "Riconoscimento visivo locale non riuscito.",
                                    null
                                )
                            }
                        }
                    } catch (_: OutOfMemoryError) {
                        main.post {
                            busy.set(false)
                            result.error("LOCAL_VISION_OOM", "Memoria insufficiente per analizzare la foto.", null)
                        }
                    } catch (_: Exception) {
                        main.post {
                            busy.set(false)
                            result.error("LOCAL_VISION_FAILED", "Impossibile leggere la foto sul dispositivo.", null)
                        }
                    }
                }
            }
    }
}

import 'dart:async';
import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:ai_orchestrator/core/orchestrator/state_engine/chat_attachment.dart';
import 'package:ai_orchestrator/core/runtime/inference/chat_turn.dart';
import 'package:ai_orchestrator/features/chat/data/services/chat_image_vision_service.dart';

/// The first offline image capability: device-side category labels, NOT a
/// general-purpose VLM. Never claim colors, counts, OCR, or details not proven
/// by the labels. Future mtmd/vision GGUF support will use a separate backend.
final class AndroidChatLocalImageVisionService implements ChatImageVisionService {
  AndroidChatLocalImageVisionService({
    MethodChannel? channel,
    bool? supportedPlatform,
  })  : _channel =
            channel ?? const MethodChannel('com.aiorchestrator/local_image_vision'),
        _supportedPlatform = supportedPlatform ??
            (!kIsWeb && defaultTargetPlatform == TargetPlatform.android);

  static const int maxImageBytes = 8 * 1024 * 1024;
  static const Duration requestTimeout = Duration(seconds: 20);
  final MethodChannel _channel;
  final bool _supportedPlatform;

  @override
  Future<ChatImageVisionResult> analyze({
    required String providerId,
    required ChatAttachment image,
    required String prompt,
    String? systemPrompt,
    List<ChatTurn> context = const <ChatTurn>[],
  }) async {
    if (providerId != 'local') {
      throw StateError('Il riconoscimento visivo locale non usa provider Cloud.');
    }
    if (!_supportedPlatform) {
      throw UnsupportedError(
        'Il riconoscimento Image offline non è ancora supportato su questa '
        'piattaforma. Non è stata inviata alcuna immagine al Cloud.',
      );
    }
    if (!image.isImage ||
        image.uploadState != ChatAttachmentUploadState.ready ||
        image.path.trim().isEmpty) {
      throw StateError('Immagine non disponibile o ancora in preparazione.');
    }
    final file = File(image.path);
    if (!await file.exists()) {
      throw StateError('Immagine originale non trovata: selezionala di nuovo.');
    }
    final fileSize = await file.length();
    if (fileSize <= 0 || fileSize > maxImageBytes) {
      throw StateError('Image LOCAL accetta immagini fino a 8 MB.');
    }
    // No raw image, user prompt, user context or secrets ever enter diagnostics.
    final result = await _channel
        .invokeMethod<List<dynamic>>('labelImage', <String, Object>{
          'path': file.path,
        })
        .timeout(requestTimeout, onTimeout: () {
          throw StateError(
            'Image LOCAL: riconoscimento troppo lento. Riprova con una foto '
            'più piccola; nessuna immagine è stata inviata al Cloud.',
          );
        });
    final labels = <_LocalImageLabel>[];
    for (final item in result ?? const <dynamic>[]) {
      if (item is! Map) continue;
      final rawName = item['label'];
      final rawConfidence = item['confidence'];
      if (rawName is! String || rawConfidence is! num) continue;
      final name = rawName.trim().replaceAll(RegExp(r'\s+'), ' ');
      final confidence = rawConfidence.toDouble();
      if (name.isEmpty || name.length > 70 ||
          !confidence.isFinite || confidence < 0.55 || confidence > 1) {
        continue;
      }
      labels.add(_LocalImageLabel(name, confidence));
    }
    labels.sort((a, b) => b.confidence.compareTo(a.confidence));
    if (labels.isEmpty) {
      return const ChatImageVisionResult(
        providerId: 'localImageLabels',
        text: 'Non ho riconosciuto categorie visive con sufficiente '
            'affidabilità in questa foto. Il riconoscitore offline attuale '
            'è limitato; non posso descrivere dettagli, colori o testo '
            'dell\'immagine. Nessun dato è stato inviato al Cloud.',
      );
    }
    final detected = labels.take(5).map(
      (label) => '${label.name} (${(label.confidence * 100).round()}%)',
    );
    return ChatImageVisionResult(
      providerId: 'localImageLabels',
      text: 'Riconoscimento visivo sul dispositivo (categorie probabili): '
          '${detected.join(', ')}.\n'
          'Queste sono etichette stimate da un classificatore offline, '
          'non una descrizione completa. Non posso ancora dedurre con '
          'affidabilità colori, quantità, testo o altri dettagli della foto. '
          'Nessuna immagine è stata inviata al Cloud.',
    );
  }
}

final class _LocalImageLabel {
  const _LocalImageLabel(this.name, this.confidence);
  final String name;
  final double confidence;
}

import 'dart:io';

import 'package:ai_orchestrator/core/orchestrator/state_engine/chat_attachment.dart';
import 'package:ai_orchestrator/features/chat/data/services/chat_local_image_vision_service.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  const channel = MethodChannel('com.aiorchestrator/local_image_vision');
  late Directory dir;
  late File file;
  late ChatAttachment attachment;
  var calls = 0;
  final messenger =
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;

  setUp(() async {
    calls = 0;
    dir = await Directory.systemTemp.createTemp('local-vision-test-');
    file = File('${dir.path}/image.png');
    await file.writeAsBytes(<int>[137, 80, 78, 71, 13, 10, 26, 10, 0, 0]);
    attachment = ChatAttachment(
      id: 'img-local',
      type: ChatAttachmentType.image,
      path: file.path,
      name: 'image.png',
      mimeType: 'image/png',
    );
  });

  tearDown(() async {
    messenger.setMockMethodCallHandler(channel, null);
    await dir.delete(recursive: true);
  });

  test('LOCAL obtains offline labels without sending prompt to native bridge',
      () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      expect(call.method, 'labelImage');
      final arguments = call.arguments as Map<Object?, Object?>;
      expect(arguments.keys, <String>['path']);
      expect(arguments['path'], file.path);
      return <Map<String, Object>>[
        <String, Object>{'label': 'Apple', 'confidence': 0.92},
        <String, Object>{'label': 'Fruit', 'confidence': 0.74},
        <String, Object>{'label': 'Guess', 'confidence': 0.15},
      ];
    });
    final service = AndroidChatLocalImageVisionService(
      channel: channel,
      supportedPlatform: true,
    );
    final response = await service.analyze(
      providerId: 'local',
      image: attachment,
      prompt: 'Dammi i colori precisi',
    );
    expect(response.providerId, 'localImageLabels');
    expect(response.text, contains('Apple (92%)'));
    expect(response.text, contains('Fruit (74%)'));
    expect(response.text, isNot(contains('Guess')));
    expect(response.text, contains('Non posso ancora dedurre'));
    expect(response.text, contains('Nessuna immagine è stata inviata al Cloud'));
    expect(calls, 1);
  });

  test('no labels yields an honest limited result', () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    final response = await AndroidChatLocalImageVisionService(
      channel: channel, supportedPlatform: true,
    ).analyze(providerId: 'local', image: attachment, prompt: '');
    expect(response.text, contains('Non ho riconosciuto categorie'));
    expect(calls, 1);
  });

  test('desktop without backend fails without forwarding the photo', () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    await expectLater(
      AndroidChatLocalImageVisionService(
        channel: channel, supportedPlatform: false,
      ).analyze(providerId: 'local', image: attachment, prompt: ''),
      throwsUnsupportedError,
    );
    expect(calls, 0);
  });

  test('invalid and oversized local photos never enter native bridge',
      () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    final service = AndroidChatLocalImageVisionService(
      channel: channel, supportedPlatform: true,
    );
    await file.delete();
    await expectLater(
      service.analyze(providerId: 'local', image: attachment, prompt: ''),
      throwsStateError,
    );
    await file.writeAsBytes(List<int>.filled(
      AndroidChatLocalImageVisionService.maxImageBytes + 1, 0,
    ));
    await expectLater(
      service.analyze(providerId: 'local', image: attachment, prompt: ''),
      throwsStateError,
    );
    expect(calls, 0);
  });

  test('Cloud provider cannot be sent through local analyzer', () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    await expectLater(
      AndroidChatLocalImageVisionService(
        channel: channel, supportedPlatform: true,
      ).analyze(providerId: 'gemini', image: attachment, prompt: ''),
      throwsStateError,
    );
    expect(calls, 0);
  });

  test('native classifier error is reported instead of fake vision output',
      () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      throw PlatformException(code: 'LOCAL_VISION_FAILED',
          message: 'Riconoscimento visivo locale non riuscito.');
    });
    await expectLater(
      AndroidChatLocalImageVisionService(
        channel: channel, supportedPlatform: true,
      ).analyze(providerId: 'local', image: attachment, prompt: ''),
      throwsA(isA<PlatformException>()),
    );
  });
}

import '../lib/local_image_labels.dart';

int passed = 0;
void check(bool condition, String name) {
  if (!condition) throw StateError('FAIL: $name');
  passed++;
}

void main() {
  final result = LocalImageLabelProcessor.fromNative(<Object?>[
    <String, Object?>{'label': ' Fruit  Bowl ', 'confidence': 0.74},
    <String, Object?>{'label': 'Apple', 'confidence': 0.92},
    <String, Object?>{'label': 'Guess', 'confidence': 0.15},
  ]);
  check(LocalImageLabelResult.providerId == 'localImageLabels', 'local origin');
  check(result.hasCategories, 'categories recognized');
  check(result.labels.length == 2, 'below threshold excluded');
  check(result.labels.first.name == 'Apple', 'descending confidence');
  check(result.labels.last.name == 'Fruit Bowl', 'whitespace normalized');
  check(result.text.contains('Apple (92%)'), 'rounded confidence');
  check(!result.text.contains('Guess'), 'low confidence excluded');
  check(result.text.contains('non una descrizione completa'), 'limits disclosed');
  check(result.text.contains('Nessuna immagine è stata inviata al Cloud'),
      'offline result does not imply Cloud transfer');

  final empty = LocalImageLabelProcessor.fromNative(<Object?>[
    null,
    123,
    {'label': '', 'confidence': 0.9},
    {'label': 'Unknown', 'confidence': double.nan},
    {'label': 'Unknown', 'confidence': double.infinity},
    {'label': 'Unknown', 'confidence': -0.2},
    {'label': 'Unknown', 'confidence': 1.01},
    {'label': 'Unknown', 'confidence': '0.9'},
    {'label': List<String>.filled(71, 'Z').join(), 'confidence': 1},
  ]);
  check(!empty.hasCategories, 'invalid inputs all rejected');
  check(empty.text.contains('Non ho riconosciuto categorie'), 'honest fallback');

  final top = LocalImageLabelProcessor.fromNative(
    List<Object?>.generate(
      12, (i) => {'label': 'Label$i', 'confidence': 0.99 - i * 0.01}),
  );
  check(top.labels.length == LocalImageLabelProcessor.maxLabels,
      'bounded top-five');
  check(top.labels.first.name == 'Label0', 'highest rank');
  check(top.labels.last.name == 'Label4', 'fifth rank');
  check(top.text.contains('Label0') && !top.text.contains('Label5'),
      'sixth category omitted');
  final boundary = LocalImageLabelProcessor.fromNative(<Object?>[
    {'label': 'Exactly', 'confidence': 0.55},
    {'label': 'JustBelow', 'confidence': 0.549},
  ]);
  check(boundary.labels.length == 1 &&
      boundary.labels.single.name == 'Exactly', 'threshold inclusive');
  check(boundary.labels.single.confidence == 0.55, 'confidence retained');
  try {
    result.labels.add(const LocalImageLabel('mutated', 1));
    throw StateError('FAIL: result should be immutable');
  } on UnsupportedError {
    passed++;
  }
  print('PASS: $passed Dart offline image-label checks');
}
